def check_girth(edges, n, min_girth):
    """Check if graph has girth at least min_girth"""
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS to find shortest cycle through start
        visited = {start: 0}
        queue = [(start, -1, 0)]  # (vertex, parent, distance)
        while queue:
            v, parent, dist = queue.pop(0)
            for neighbor in adj[v]:
                if neighbor == parent:
                    continue
                if neighbor in visited:
                    # Found a cycle
                    cycle_len = dist + visited[neighbor] + 1
                    if cycle_len < min_girth:
                        return False
                else:
                    visited[neighbor] = dist + 1
                    queue.append((neighbor, v, dist + 1))
    return True

def check_colorable(edges, n, k):
    """Check if graph is k-colorable using backtracking"""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in adj[v]:
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

