def get_all_cycles(edges, n, max_len):
    """Find all cycles up to max_len"""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    cycles = set()
    for start in range(n):
        # DFS to find cycles
        stack = [(start, [start])]
        while stack:
            v, path = stack.pop()
            if len(path) > max_len:
                continue
            for neighbor in adj[v]:
                if neighbor == start and len(path) >= 3:
                    cycle = tuple(sorted(path))
                    cycles.add(cycle)
                elif neighbor not in path and len(path) < max_len:
                    stack.append((neighbor, path + [neighbor]))
    return cycles

def has_short_cycle(edges, n, min_girth):
    """Check if there's a cycle shorter than min_girth"""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS from each vertex
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        idx = 0
        while idx < len(queue):
            v = queue[idx]
            idx += 1
            for neighbor in adj[v]:
                if neighbor == parent.get(v, -1):
                    continue
                if neighbor in dist:
                    cycle_len = dist[v] + dist[neighbor] + 1
                    if cycle_len < min_girth:
                        return True
                else:
                    dist[neighbor] = dist[v] + 1
                    parent[neighbor] = v
                    queue.append(neighbor)
    return False

