from pysat.solvers import Glucose3
import random

n = 21
A_size = 10
B_size = 11

def var(i, j):
    return i * B_size + j + 1

def check_girth_bipartite(edges, A_size, B_size):
    """Check girth of bipartite graph"""
    adj_a = [set() for _ in range(A_size)]
    adj_b = [set() for _ in range(B_size)]
    for a, b in edges:
        adj_a[a].add(b - A_size)
        adj_b[b - A_size].add(a)

    # Check for 4-cycles
    for a1 in range(A_size):
        for a2 in range(a1+1, A_size):
            common = adj_a[a1] & adj_a[a2]
            if len(common) >= 2:
                return False

    # Check for 6-cycles using BFS
    for start_a in range(A_size):
        # BFS from start_a, looking for cycles
        # Level 0: start_a
        # Level 1: neighbors of start_a in B
        # Level 2: neighbors of those in A (excluding start_a)
        # Level 3: neighbors of those in B
        # Level 4: neighbors of those in A
        # If any reaches start_a, we have a 6-cycle

        visited_b = {}  # b -> distance
        queue = []
        for b in adj_a[start_a]:
            visited_b[b] = 1
            queue.append((b, 1))

        idx = 0
        while idx < len(queue):
            v, dist = queue[idx]
            idx += 1
            if dist >= 5:
                continue
            # v is in B, go to A
            for a in adj_b[v]:
                if a == start_a and dist == 4:
                    return False  # Found 6-cycle
                if a != start_a:
                    # Go to B neighbors
                    for b2 in adj_a[a]:
                        if b2 not in visited_b:
                            visited_b[b2] = dist + 2
                            queue.append((b2, dist + 2))

    return True

# Try SAT with iterative constraint addition
def solve_sat_iterative():
    solver = Glucose3()

    # Add 4-cycle constraints
    for i1 in range(A_size):
        for i2 in range(i1+1, A_size):
            for j1 in range(B_size):
                for j2 in range(j1+1, B_size):
                    clause = [-var(i1,j1), -var(i1,j2), -var(i2,j1), -var(i2,j2)]
                    solver.add_clause(clause)

    # Try to find a solution with many edges
    # Use a heuristic: try to set many variables to true
    for trial in range(100):
        random.seed(trial)

        # Create a fresh solver for each trial
        solver2 = Glucose3()

        # Add 4-cycle constraints
        for i1 in range(A_size):
            for i2 in range(i1+1, A_size):
                for j1 in range(B_size):
                    for j2 in range(j1+1, B_size):
                        clause = [-var(i1,j1), -var(i1,j2), -var(i2,j1), -var(i2,j2)]
                        solver2.add_clause(clause)

        # Try to force at least 40 edges using assumptions
        all_vars = [var(i, j) for i in range(A_size) for j in range(B_size)]

        # Randomly order and try to set as many as possible
        random.shuffle(all_vars)

        # Use incremental solving with assumptions
        assumptions = []
        for v in all_vars[:45]:  # Try to set 45 edges
            assumptions.append(v)

        if solver2.solve(assumptions=assumptions):
            model = solver2.get_model()
            edges = []
            for i in range(A_size):
                for j in range(B_size):
                    if model[var(i,j)-1] > 0:
                        edges.append((i, A_size + j))

            if check_girth_bipartite(edges, A_size, B_size):
                print(f"Found {len(edges)} edges")
                return edges

    return None

