import random

n = 21
A_size = 10
B_size = 11
target_edges = 40
min_girth = 8

def check_girth_bipartite(edges, A_size, B_size):
    """Check girth of bipartite graph"""
    adj_a = [set() for _ in range(A_size)]
    adj_b = [set() for _ in range(B_size)]
    for a, b in edges:
        adj_a[a].add(b - A_size)
        adj_b[b - A_size].add(a)

    # Check for 4-cycles
    for a1 in range(A_size):
        for a2 in range(a1+1, A_size):
            common = adj_a[a1] & adj_a[a2]
            if len(common) >= 2:
                return False

    # Check for 6-cycles
    for start_a in range(A_size):
        # BFS to find if there's a path of length 5 from start_a back to start_a
        # Level 0: start_a (A)
        # Level 1: B neighbors
        # Level 2: A neighbors (not start_a)
        # Level 3: B neighbors
        # Level 4: A neighbors
        # Level 5: B neighbors - if any is a neighbor of start_a, we have a 6-cycle

        # Actually, let's do proper BFS
        dist = {start_a: 0}
        queue = [start_a]
        idx = 0
        while idx < len(queue):
            v = queue[idx]
            idx += 1
            if dist[v] >= 5:
                continue
            if v < A_size:  # v in A
                neighbors = [A_size + j for j in adj_a[v]]
            else:  # v in B
                neighbors = list(adj_b[v - A_size])
            for neighbor in neighbors:
                if neighbor == start_a:
                    if dist[v] + 1 < min_girth:
                        return False
                elif neighbor not in dist:
                    dist[neighbor] = dist[v] + 1
                    queue.append(neighbor)

    return True

def count_bad_cycles(edges, A_size, B_size):
    """Count number of 4-cycles and 6-cycles"""
    adj_a = [set() for _ in range(A_size)]
    adj_b = [set() for _ in range(B_size)]
    for a, b in edges:
        adj_a[a].add(b - A_size)
        adj_b[b - A_size].add(a)

    bad = 0

    # Count 4-cycles
    for a1 in range(A_size):
        for a2 in range(a1+1, A_size):
            common = adj_a[a1] & adj_a[a2]
            bad += len(common) * (len(common) - 1) // 2

    # Count 6-cycles (more expensive)
    for start_a in range(A_size):
        # Find all paths of length 5 from start_a back to start_a
        # Use BFS with path tracking
        paths = {start_a: [[start_a]]}
        for step in range(1, 6):
            new_paths = {}
            for v, path_list in paths.items():
                if v < A_size:
                    neighbors = [A_size + j for j in adj_a[v]]
                else:
                    neighbors = list(adj_b[v - A_size])
                for neighbor in neighbors:
                    if neighbor == start_a and step == 5:
                        bad += len(path_list)
                    elif neighbor != start_a and step < 5:
                        if neighbor not in new_paths:
                            new_paths[neighbor] = []
                        for path in path_list:
                            if neighbor not in path:
                                new_paths[neighbor].append(path + [neighbor])
            paths = new_paths

    return bad

# Local search
def local_search():
    random.seed(42)

    # Start with a random set of edges
    all_possible = [(i, A_size + j) for i in range(A_size) for j in range(B_size)]

    # Start with 45 random edges
    edges = set(random.sample(all_possible, 45))

    best_edges = None
    best_score = -float('inf')

    for iteration in range(100000):
        bad = count_bad_cycles(list(edges), A_size, B_size)
        score = len(edges) - 10 * bad

        if bad == 0 and len(edges) >= target_edges:
            print(f"Found solution with {len(edges)} edges at iteration {iteration}")
            return list(edges)

        if score > best_score:
            best_score = score
            best_edges = set(edges)

        # Try to improve
        if bad > 0:
            # Remove a random edge that's part of a bad cycle
            edge_to_remove = random.choice(list(edges))
            edges.remove(edge_to_remove)
        else:
            # Try to add an edge
            remaining = [e for e in all_possible if e not in edges]
            if remaining:
                edge_to_add = random.choice(remaining)
                test_edges = edges | {edge_to_add}
                if count_bad_cycles(list(test_edges), A_size, B_size) == 0:
                    edges.add(edge_to_add)
                else:
                    # Remove a random edge and add a new one
                    edge_to_remove = random.choice(list(edges))
                    edges.remove(edge_to_remove)
                    edges.add(edge_to_add)

    if best_edges:
        bad = count_bad_cycles(list(best_edges), A_size, B_size)
        print(f"Best: {len(best_edges)} edges, {bad} bad cycles")
        return list(best_edges) if bad == 0 else None

    return None

result = local_search()
if result:
    print(f"Solution: {len(result)} edges")
    print(result)
